<script setup lang="ts">import{onMounted,ref}from"vue";import{bzaApi,hasBzaPermission}from"../auth/session";const groupId=ref("GENERAL"),rows=ref<any[]>([]),error=ref("");async function load(){try{rows.value=await bzaApi(`/api/bza/attachments?groupId=${encodeURIComponent(groupId.value)}`)}catch(e){error.value=e instanceof Error?e.message:String(e)}}async function upload(e:Event){const f=e.currentTarget as HTMLFormElement,d=new FormData(f);d.set("groupId",groupId.value);await bzaApi('/api/bza/attachments',{method:'POST',body:d});f.reset();load()}async function security(r:any,status:string){const reason=prompt('조치 사유')||'';if(!reason)return;await bzaApi(`/api/bza/attachments/${r.attachmentId}/security`,{method:'POST',body:JSON.stringify({scanStatus:status,dataClassification:r.dataClassification||'INTERNAL',quarantineYn:status==='QUARANTINED'?'Y':'N',useYn:r.useYn||'Y',reason})});load()}async function recheck(r:any){const reason=prompt('재검사 사유')||'';if(reason){await bzaApi(`/api/bza/attachments/${r.attachmentId}/recheck?reason=${encodeURIComponent(reason)}`,{method:'POST'});load()}}onMounted(load);</script>
<template><div class="page-stack"><section class="card"><div class="card-head"><div><p class="eyebrow">ATTACHMENT</p><h2>첨부파일 보안 운영</h2></div></div><label>그룹 ID<input v-model="groupId" @change="load"></label><form v-if="hasBzaPermission('ATTACHMENT','WRITE')" @submit.prevent="upload"><input name="reason" placeholder="감사 사유" required><input name="file" type="file" required><button class="primary">업로드</button></form><p v-if="error" class="error-banner">{{error}}</p></section><section class="card"><div class="table-wrap"><table><thead><tr><th>파일</th><th>검사</th><th>분류</th><th>격리</th><th>보존</th><th>조치</th></tr></thead><tbody><tr v-for="r in rows" :key="r.attachmentId"><td>{{r.originalFileName}}</td><td>{{r.scanStatus}}</td><td>{{r.dataClassification}}</td><td>{{r.quarantineYn}}</td><td>{{r.retentionUntil||'-'}}</td><td><button @click="recheck(r)">재검사</button><button @click="security(r,'CLEAN')">CLEAN</button><button @click="security(r,'QUARANTINED')">격리</button></td></tr></tbody></table></div></section></div></template>
